class SgNumberLocaleData {
  const SgNumberLocaleData({required this.numberDecimal, required this.numberGroup, required this.currencyDecimal, required this.currencyGroup, required this.placement, required this.symbols});

  /// `new Intl.NumberFormat(locale).formatToParts(1000.1)` (group ausente = ','; decimal ausente = '.').
  final String numberDecimal;
  final String numberGroup;

  /// Idem com `style: 'currency'`.
  final String currencyDecimal;
  final String currencyGroup;

  /// Posicao do simbolo com `currencySymbolPlacement: 'auto'`, por `currencyDisplay`.
  final Map<String, String> placement;

  /// Moeda -> [symbol, narrowSymbol, name]; `code` e o proprio codigo. Moeda fora da tabela: o codigo.
  final Map<String, List<String>> symbols;
}

